// 2026-10-03 "fixes round 3" pass, Section 5 — one-time engineering script.
// Generates the FULL, user-authorized 35-image set (10 styles + 25 niches),
// using the user's own exact prompts verbatim (never rewritten/shortened),
// via the internal generate-style-preview-asset function (no jobs row, no
// user credit charge — see that function's own header comment). Real Nano
// Banana 2 (google:4@3) 1K 16:9 cost: $0.04945 x 35 = $1.73075, explicitly
// authorized by the user. Uploads to Supabase Storage first (the function's
// only mode); a follow-up script downloads+converts+vendors each into
// public/images/styles/ or public/images/niches/ as real static webp files.
import { config as loadEnv } from "dotenv";
loadEnv({ path: ".env.local", quiet: true });
import { createClient } from "@supabase/supabase-js";

const SUPABASE_URL = process.env.SUPABASE_URL;
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
const admin = createClient(SUPABASE_URL, SERVICE_KEY);
const TEST_EMAIL = "upwardlift6@gmail.com";

async function mintSession() {
  const { data, error } = await admin.auth.admin.generateLink({ type: "magiclink", email: TEST_EMAIL });
  if (error) throw error;
  const anon = createClient(SUPABASE_URL, process.env.SUPABASE_ANON_KEY ?? SERVICE_KEY);
  const { data: verify, error: verifyError } = await anon.auth.verifyOtp({ token_hash: data.properties.hashed_token, type: "email" });
  if (verifyError) throw verifyError;
  return verify.session.access_token;
}
async function callFn(name, accessToken, body) {
  const res = await fetch(`${SUPABASE_URL}/functions/v1/${name}`, {
    method: "POST",
    headers: { Authorization: `Bearer ${accessToken}`, apikey: process.env.SUPABASE_ANON_KEY ?? SERVICE_KEY, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  const json = await res.json().catch(() => ({}));
  return { status: res.status, ok: res.ok, json };
}

