async function main() {
  const accessToken = await mintSession();
  const all = [...STYLES.map((s) => ({ ...s, category: "styles" })), ...NICHES.map((n) => ({ ...n, category: "niches" }))];
  console.log(`Session minted. Generating ${all.length} images (Nano Banana 2, 1K, 16:9)...\n`);

  const results = [];
  let totalCost = 0;
  for (const item of all) {
    process.stdout.write(`  [${item.category}] ${item.id} ... `);
    const res = await callFn("generate-style-preview-asset", accessToken, { styleId: item.id, prompt: item.prompt });
    if (!res.ok) {
      console.log("FAILED", res.status, JSON.stringify(res.json));
      results.push({ id: item.id, category: item.category, ok: false, error: res.json });
      continue;
    }
    console.log("OK");
    totalCost += res.json.costUSD;
    results.push({ id: item.id, category: item.category, ok: true, publicUrl: res.json.publicUrl, costUSD: res.json.costUSD });
  }

  console.log("\n=== SUMMARY ===");
  const failed = results.filter((r) => !r.ok);
  console.log(`${results.filter((r) => r.ok).length}/${all.length} succeeded. Total cost: $${totalCost.toFixed(4)}`);
  if (failed.length) console.log("FAILED:", JSON.stringify(failed, null, 2));
  console.log("\nFull results:", JSON.stringify(results, null, 2));
}
main().catch((e) => { console.error("GENERATION FAILED:", e); process.exit(1); });
